	private static int check(int n, int x) {

		if(n > x-3) n = x-3;

		int ans = 0;
		for (int i = 1; i <= n-2; i++) {
			for (int j = i+1; j <= n-1; j++) {
				for (int k = j+1; k <= n; k++) {
					if(i + j + k == x) ans++;
				}
			}
		}
		return ans;
	}
}

