                if(n == 0  && x == 0) {
                    break;
                }

                int count = 0;

                for(int i = 1; i <= (n - 2); i++) {
                    if(i > (x - 2)) {
                        break;
                    }
                    for(int j = (i + 1); j <= (n - 1); j++) {
                        if(i + j > x - 1) {
                            continue;
                        }
                        for(int k = (j + 1); k <= n; k++) {
                            int sum = i + j + k;
                            if(sum == x) {
                                count++;
                            }
                        }
                    }
                }

