    int m=Integer.parseInt(scan.next());
    int l=Integer.parseInt(scan.next());
    long[][] arrayA=new long[n][m];
    for(int i=0;i<arrayA.length;i++){
      for(int j=0;j<arrayA[i].length;j++){
        arrayA[i][j]=Long.parseLong(scan.next());
      }
