		while(true){
			String str=sc.next();
			if(str.equals("-")){
				break;
			}else{
				char[] ar = str.toCharArray();
				Queue<Character> q = new LinkedList<Character>();
				for(char ch:ar){
					q.offer(ch);
				}
				int m=sc.nextInt();
				for(int i=0;i<m;i++){
					int h=sc.nextInt();
					for(int j=0;j<h;j++){
