        for(int c=1; c<=N; c++) {
          sum += gcd(a, gcd(b,c));
        }
      }
    }
    System.out.println(sum);
  }

  public static int gcd(int a, int b) {
    int r = a % b;
    while(r != 0) {
      a = b;
      b = r;
      r = a % b;
    }
    return b;
  }
}

