				for(int k = j; k <= n; k++) {
					if(i == j && j == k) {
						sum += gcd3(i, j,k);
					}else if(i == j || j == k || k == i){
						sum += 3*gcd3(i, j,k);
					}else {
						sum += 6*gcd3(i, j,k);
					}
				}
			}
		}

		System.out.println(sum);
	}

	long gcd3(int a , int b, int c) {
		int firstGCD = gcd(a,b);
		int secondGCD = gcd(firstGCD, c);
		return (long)secondGCD;
	}

	int gcd(int a,int b) {

		if(a < b) {
			int temp = a;
			a = b;
			b = temp;
		}

		int key = b*1000+a;
		if(gcdMap.containsKey(key)) {
			return gcdMap.get(key);
		}

		int r = a % b;
		while(r != 0) {
			a = b;
			b = r;
			r = a % b;
		}

		gcdMap.put(key, b);
		return b;
	}



