            n = Math.abs(n - (n/k - 1)*k);
        }
        else if(n<k){
            n = Math.abs(n - (k/n - 1)*n);
        }
        n = Math.min(n, min);
        min = n;
        while(true){
            long tmp = Math.abs(n-k);
            if(tmp < min){
                min = tmp;
                n = tmp;
            }
            else{
                break;
            }
        }

        System.out.println(min);
    }
}

