		HashMap<String, Integer> mp = new HashMap<>();
		int ma = 0;
		for (int i = 0; i < n; i++) {
			String s = ir.next();
			if (!mp.containsKey(s)) {
				mp.put(s, 1);
				ma = Math.max(ma, 1);
			} else {
				ma = Math.max(ma, mp.get(s) + 1);
				mp.put(s, mp.get(s) + 1);
			}
		}
		ArrayList<String> l = new ArrayList<>();
		for (Map.Entry<String, Integer> e : mp.entrySet()) {
			if (e.getValue() == ma)
				l.add(e.getKey());
		}
		Collections.sort(l);
		for (String str : l) {
			out.println(str);
		}
