    long lcm(long a, long b){return a / gcd(a, b) * b;}

    void solve(){
        int N = in.nextInt();
        MultiSet<String> multiSet = new MultiSet<>();
        for(int i = 0; i < N; i++) multiSet.add(in.nextStr());
        long max = 0;
        for(long v : multiSet.values()) max = Math.max(max, v);
        for(String s : multiSet.keySet()) if(multiSet.count(s) == max) out.println(s);
    }

    class MultiSet<K extends Comparable<K>> extends TreeMap<K,Integer>{
        int sum = 0;

        public int sum(){
            return this.sum;
        }

        public int count(K k){
            return this.getOrDefault(k, 0);
        }

        public int add(K k) {
            int res = this.count(k) + 1;
            this.put(k, res);
            sum++;
            return res;
        }

        public int sub(K k){
            if(!this.containsKey(k)) return -1;
            int res = this.count(k) - 1;
            if(res == 0) this.remove(k);
            else this.put(k, res);
            sum--;
            return res;
        }

        public int subAll(K k){
            if(!this.containsKey(k)) return -1;
            int cnt = this.count(k);
            this.remove(k);
            sum -= cnt;
            return cnt;
        }
    }

