	public String[] attack_survival(int n, int k, int[] a) {
		int i;
		int[] player = new int[n];
		String[] result = new String[n];
		for(i = 0; i < n; i++) {
			player[i] = k + (-a.length);
		}

		for(int p : a) {
			player[p - 1] += 1;
		}
		for(i = 0; i < n; i++) {
			if(player[i] > 0) {
				result[i] = "Yes";
			}else {
				result[i] = "No";
			}
		}

		return result;
	}
}

