    static class TaskC {
        public void solve(int testNumber, FastReader s, PrintWriter out) {
            int n = s.nextInt();
            int k = s.nextInt();
            int q = s.nextInt();
            int[] arr = s.nextIntArray(q);
            int[] neg = new int[n];
            Arrays.fill(neg, q);

            int[] ans = new int[n];
            Arrays.fill(ans, k);
            for (int i = 0; i < q; i++) {
