        int sum = 0;
        for (int i = 0; i < n; ++i)
            a[i] = scanner.nextInt() - 1;
        for (int i = 0; i < n; ++i) {
            b[i] = scanner.nextInt();
            sum += b[i];
        }
        for (int i = 0; i < n - 1; ++i)
            c[i] = scanner.nextInt();
