		//料理の種類の合計をセット
		int intDishTotal = mScanner.nextInt();

		//食べた料理の順番をセット
		int[] intArrEatOrder = CreateArrayFromInput(intDishTotal);

		//各料理の満足度Bをセット
		int[] intArrSatisfactionB = CreateArrayFromInput(intDishTotal);

