public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		char[] s = ir.next().toCharArray();
		char[] t = ir.next().toCharArray();
		int ct = 0;
		for (int i = 0; i < 3; i++)
			if (s[i] == t[i])
				ct++;
