class Main {
    FileInputStream fs;
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    void solve() {
        String a = ns(), b = ns();
        int res = 0;
        for(int i = 0; i < 3; i++) {
            if(a.charAt(i) == b.charAt(i))
                res++;
        }
        out.println(res);
