        public void solve(int testNumber, InputReader s, PrintWriter w) {
            int n = s.nextInt(), x = s.nextInt();
            int count = 1, curr = 0;
            for (int i = 0; i < n; i++) {
                curr += s.nextInt();
                if (curr <= x)
                    count++;
            }
