public class Main {

  static FastScanner sc = new FastScanner();

  static long[] memo;
  static int[] a;

  static long MOD = (long)1e9+7;

  public static void main(String[] args) {

    int N = sc.nextInt();

    memo = new long[N+2];

    int M = sc.nextInt();

    a = new int[M+2];
    a[0] = -1;
    for (int i=1; i<=M; i++) {
      a[i] = sc.nextInt();
    }
    a[M+1] = N+1;

    long ans = 1;
    for (int i=0; i<M+1; i++) {
      ans = (ans * f(a[i+1]-a[i]-1)) % MOD;
    }

    System.out.println(ans);

  }

  public static long f(int N) {

    if (memo[N] > 0) {
      return memo[N];
    }

    if (N == 0) {
      return 0;
    }

    if (N == 1) {
      return 1;
    }

    long left = f(N-2);
    long right = f(N-1);

    return memo[N] = (left + right) % MOD;
  }

