    public static void main(String args[]) throws IOException {
        Scan sc = new Scan();
        int n = sc.scanInt();
        int[] stairs = new int[n+1];
        stairs[0]=1;
        int m = sc.scanInt();
        while(m-- > 0)
            stairs[sc.scanInt()]=-1;
        for(int i = 1; i <= n; ++i){
            if(stairs[i] == -1)
                continue;
            else {
                int prev = Math.max(0, stairs[i-1]);
                int pprev = (i>=2 ? Math.max(0, stairs[i-2]):0);
                stairs[i] = modAdd(prev, pprev);
            }
        }
        System.out.println(stairs[n]);

    }

    static int modAdd(int a, int b){
        return (int)(((long)a+b)%mod);
    }
}

class Scan
{
    private byte[] buf=new byte[1024];
    private int index;
