    static class CTypicalStairs {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            int[] a = in.readIntArray(m);

            long[] dp = new long[n + 1];
            Arrays.fill(dp, 1);
            for (int i = 0; i < m; i++) {
                dp[a[i]] = 0;
            }
            for (int i = 2; i <= n; i++) {
