		for(int i = 0; i < N; i++){
			if(!isNotSafe[i+1]){
				dp[i+1] = (dp[i+1] + dp[i]) % MOD;
			}
			if(i+2 <= N && !isNotSafe[i+2]){
				dp[i+2] = (dp[i+2] + dp[i]) % MOD;
			}
		}
		out.println(dp[N]);
	}

	/* end solve */

	/* main */
	public static void main(String[] args) throws Exception {
		new Main().m();
	}

	void m() throws Exception {
		if(isDebug) in = new FastScanner(new FileInputStream(fileName));
		solve();
		out.flush();
	}
	/* end main */
}
