public class Main {

  static FastScanner sc = new FastScanner();

  static long MOD = (long)1e9+7;

  public static void main(String[] args) {

    int N = sc.nextInt();
    int M = sc.nextInt();

    long[] dp = new long[N+1];

    Arrays.fill(dp, 1);

    for (int i=0; i<M; i++) {
      dp[sc.nextInt()] = 0;
    }

    for (int i=2; i<=N; i++) {
      dp[i] = ((dp[i-2] + dp[i-1]) * dp[i]) % MOD;
    }

    System.out.println(dp[N]);

  }

