		char[] s = sc.next().toCharArray();
		int cnt = 0;
		int max = 0;
		for (int i = 0; i < s.length; i++) {
			if (s[i] == 'A' || s[i] == 'C' || s[i] == 'G' || s[i] == 'T') {
				cnt++;
			} else {
				if (max < cnt) {
					max = cnt;
				}
