    }

    static long getAns(int n) {
        // System.out.println("n = "+n);
        if (n == 0)
            return 0;
        if (n == 1)
            return Math.abs(h[1] - h[0]);

        long ans1;
        if (dp[n - 1] == 0)
            dp[n - 1] = getAns(n - 1);
        ans1 = dp[n - 1];
        ans1 += Math.abs(h[n] - h[n - 1]);

        long ans2;
        if (dp[n - 2] == 0)
            dp[n - 2] = getAns(n - 2);
        ans2 = dp[n - 2];
        ans2 += Math.abs(h[n] - h[n - 2]);
        // System.out.println("n = "+n+" ans1 = "+ans1+" ans2 = "+ans2);

        return Math.min(ans1, ans2);
    }

}

