            int[] arr = s.nextIntArray(n);
            int[] dp = new int[n];
            Arrays.fill(dp, Integer.MAX_VALUE);
            dp[n - 1] = 0;
            for (int i = n - 2; i >= 0; i--) {
                for (int j = i + 1; j <= Math.min(i + k, n - 1); j++) {
