        for(int i = 0;i < N;i++) {
            H[i] = nextInt();
        }

        double closest = Double.MAX_VALUE;
        int ans = -1;
        for(int i = 0;i < N;i++) {
            double avg = T - H[i] * 0.006;
            double abs = Math.abs(A - avg);
            if (closest > abs) {
                closest = abs;
                ans = i + 1;
            }
        }

        out.println(ans);
    }

    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

