    static class COtoshidama {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int N = in.nextInt();
            int Y = in.nextInt();
            int[] v = {10000, 5000, 1000};
            int c10k = 0;
            int c5k = 0;
            int c1k = Y / v[2];
            int rest = c1k - N;
            for (int i1k = 0; i1k <= N; i1k++) {
                if (rest < 4) break;
                else if (rest % 9 == 0 && 10 * (rest / 9) <= c1k) {
                    c10k = rest / 9;
                    c1k -= 10 * c10k;
                    break;
                } else {
                    rest -= 4;
                    c5k += 1;
                    c1k -= 5;
                }

            }
            if (c10k + c5k + c1k != N) {
                out.println("-1 -1 -1");
                return;
            }
            out.println(c10k + " " + c5k + " " + c1k);
