public class Main {

	public static void main(String[] args) {
		Main main = new Main();
		main.run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);

		String[] A=sc.next().split("");
		String[] B=sc.next().split("");
		String[] C=sc.next().split("");

		Deque<String> handA=new ArrayDeque<String>();
		Deque<String> handB=new ArrayDeque<String>();
		Deque<String> handC=new ArrayDeque<String>();


		for (int i = 0; i < A.length; i++) {
			handA.add(A[i]);
		}

		for (int i = 0; i < B.length; i++) {
			handB.add(B[i]);
		}

		for (int i = 0; i < C.length; i++) {
			handC.add(C[i]);
		}

		String top=handA.poll();

		while(true) {

			if(top.equals("a")) {
				if(!handA.isEmpty()) {
					top=handA.poll();
				}else {
					pln("A");
					return;
				}
			}else if(top.equals("b")) {
				if(!handB.isEmpty()) {
					top=handB.poll();
				}else {
					pln("B");
					return;
				}

			}else {
				if(!handC.isEmpty()) {
					top=handC.poll();
				}else {
					pln("C");
					return;
				}
			}

		}

	}

	//以下テンプレート

	public static int[] extgcd(int a, int b) {

		int x0 = 1;
		int x1 = 0;

		int y0 = 0;
		int y1 = 1;

		while (b != 0) {
			int q = a / b;
			int r = a % b;

			int x2 = x0 - q * x1;
			int y2 = y0 - q * y1;

			a = b;
			b = r;

			x0 = x1;
			x1 = x2;

			y0 = y1;
			y1 = y2;
		}

		return new int[] { a, x0, y0 };

	}

	static int gcd(int a, int b) {

		if (b == 0)
			return a;

		if (a < b) {
			int t = a;
			a = b;
			b = t;
		}

		return gcd(b, a % b);

	}

	static int lcm(int a, int b) {
		return a * b / gcd(a, b);
	}

	static void swap(int[] a) {
		int t;

		t = a[0];
		a[0] = a[1];
		a[1] = t;

		return;
	}

	static <T> void output(List<T> list) {

		for (int i = 0; i < list.size(); i++) {
			System.out.print(list.get(i));

			if (i != list.size() - 1) {
				System.out.print(" ");
			} else {
				nl();
			}
		}

	}

