			Queue<Character> cq = new ArrayDeque<Character>();

			for (int i = 0; i < a.length; i++) {
				aq.add(a[i]);
			}
			for (int i = 0; i < b.length; i++) {
				bq.add(b[i]);
			}
			for (int i = 0; i < c.length; i++) {
				cq.add(c[i]);
			}

			char cur = aq.remove();
			while (true) {

				if (cur == 'a') {
					if (aq.isEmpty()) {
						out.println("A");
						return;
					}
					cur = aq.remove();
				} else if (cur == 'b') {
					if (bq.isEmpty()) {
						out.println("B");
						return;
					}
					cur = bq.remove();
				} else if (cur == 'c') {
					if (cq.isEmpty()) {
						out.println("C");
						return;
					}
					cur = cq.remove();
				}

			}

		}
	}

