    List<Deque<Character>> listDeque = new ArrayList<>();
    for (char[] ss : sm) {
      Deque<Character> deque = new ArrayDeque<>();
      for (char c : ss) {
        deque.addLast(c);
      }
      listDeque.add(deque);
    }

    int player = 0;
    while (true) {
      if (listDeque.get(player).isEmpty()) {
        return "" + (char)('A' + player);
