                if (s.charAt(j) == letters[i]) freq[i]++;
            }
        }
    }

    static int findOddSum(int[] freq) {
        int sum = 0;
        for (int i = 0; i < 26; i++) {
            if (freq[i] % 2 != 0) sum++;
        }
        return sum;
    }

    /****************************************
     ******* IO STUFF STARTS FROM HERE ******
     ****************************************/

