    String s = sc.next();
    boolean[] a = new boolean[26];
    for(int i=0;i<s.length();i++){
      a[s.charAt(i)-'a']=!a[s.charAt(i)-'a'];
    }
    for(int i='a';i<='z';i++){
      if(a[i-'a']){
        out.println("No");
        out.flush();
        return;
      }
    }
    out.println("Yes");
    out.flush();
  }
}

