	private static final class Solver {
		public void solve() {
			char[] line = in.next().toCharArray();
			ArrayDeque<Character> deque = new ArrayDeque<>();
			for (char c : line) {
				if (c == 'B') {
					if (!deque.isEmpty()) deque.pollLast();
				} else {
					deque.addLast(c);
