public class Main {
  private static String solve(char[] cs) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : cs) {
      if (c != 'B') {
        stack.addLast(c);
      } else if (!stack.isEmpty()) {
        stack.pollLast();
      }
    }
    StringBuffer sb = new StringBuffer();
    for (char c : stack) {
      sb.append(c);
    }
    return sb.toString();
  }

